begin;
select plan(18);
select is((select count(*)::integer from public.collector_edge_sources where slug in ('edps','ec','calprivacy','oaic','ca-opc','hk-pcpd','eu-parliament','eu-council','eur-lex','cn-cac','cn-tc260')),11,'all 11 new sources tracked regardless of environment seed size');
select is((select count(*)::integer from public.collector_edge_sources e join public.sources s on s.id=e.source_id where s.parser_config->>'expansion_phase' in ('1','2')),11,'no phase 1/2 source silently omitted');
select is((select count(*)::integer from public.collector_edge_sources e join public.sources s on s.id=e.source_id where s.parser_config->>'expansion_phase' in ('1','2') and s.is_active),8,'eight phase 1/2 routes are active after pending reviews');
select is((select count(*)::integer from public.collector_cloud_routes r join public.collector_edge_sources e on e.source_id=r.source_id where r.enabled and e.slug in ('ec','eu-parliament')),2,'two cloud exceptions explicitly routed');
select ok(not exists(select 1 from public.collector_cloud_routes r join public.collector_edge_sources e on e.source_id=r.source_id where r.enabled and e.slug in ('calprivacy','oaic','ca-opc','cn-cac','cn-tc260')),'five verified Edge sources are not double consumed');
select ok(not exists(select 1 from public.collector_edge_sources e join public.sources s on s.id=e.source_id where s.parser_config->>'expansion_phase' in ('1','2') and ((e.state->>'since')::date<>(now() at time zone 'Asia/Seoul')::date-2 or (e.state->>'until')::date<>(now() at time zone 'Asia/Seoul')::date)),'new sources initialize exactly three calendar days');
select ok(not exists(select 1 from public.sources s where s.parser_config->>'expansion_phase' in ('1','2') and s.poll_interval_minutes<>1440),'phase 1/2 sources retain daily cadence');
select is((select count(*)::integer from public.sources s join public.collector_edge_sources e on e.source_id=s.id join public.collector_cloud_routes r on r.source_id=s.id where e.slug='edps' and s.is_active and s.source_kind='rss' and s.start_url='https://social.edps.europa.eu/@EDPS.rss' and s.parser_config->>'collector_executor'='cloud-python' and r.enabled),1,'EDPS Mastodon RSS uses its enabled cloud-python route');
select is((select count(*)::integer from public.sources s left join public.collector_edge_sources e on e.source_id=s.id left join public.collector_cloud_routes r on r.source_id=s.id where (e.slug in ('hk-pcpd','eu-council','eur-lex') or s.id='430bd32d-19b1-4752-8280-7b2d2acbda88'::uuid) and not s.is_active and not coalesce(r.enabled,false)),4,'PCPD, Council, EUR-Lex and FTC remain inactive with disabled cloud routes');
select is((select count(*)::integer from public.sources s left join public.collector_edge_sources e on e.source_id=s.id where ((e.slug in ('hk-pcpd','eu-council') or s.id='430bd32d-19b1-4752-8280-7b2d2acbda88'::uuid) and s.parser_config->>'collector_executor'='hold' and s.terms_reviewed_at is null) or (e.slug='eur-lex' and s.parser_config->>'collector_executor'='chatgpt-web' and s.is_active=false)),4,'held executor policy remains explicit for three sources and EUR-Lex remains inactive');
select ok(private.collector_cloud_cursor_valid('{"page":"https://ec.europa.eu/commission/presscorner/api/latestnews?language=en","offset":0}'::jsonb,'ec'),'EC official API cursor allowed');
select ok(private.collector_cloud_cursor_valid('{"page":"https://www.europarl.europa.eu/rss/doc/press-releases/en.xml","offset":0}'::jsonb,'eu-parliament'),'Parliament official RSS cursor allowed');
select ok(not private.collector_cloud_cursor_valid('{"page":"https://evil.example/","offset":0}'::jsonb,'ec'),'new cloud routes cannot use arbitrary hosts');
select ok(not has_function_privilege('anon','public.collector_cloud_take(text,text)','EXECUTE') and not has_function_privilege('authenticated','public.collector_cloud_take(text,text)','EXECUTE'),'cloud collection remains private');
select ok(private.collector_cloud_cursor_valid('{"page":"https://www.europarl.europa.eu/rss/doc/press-releases/en.xml","offset":0,"frozen_urls":["https://www.europarl.europa.eu/news/en/press-room/20261020IPR48312/"],"frozen_next":null}'::jsonb,'eu-parliament'),'committed URL snapshot resumes privately');
select ok(not private.collector_cloud_cursor_valid('{"page":"https://www.europarl.europa.eu/rss/doc/press-releases/en.xml","offset":0,"frozen_urls":["https://evil.example/data"],"frozen_next":null}'::jsonb,'eu-parliament'),'frozen detail identities cannot leave source');
select ok(not private.collector_cloud_cursor_valid('{"page":"https://www.europarl.europa.eu/rss/doc/press-releases/en.xml","offset":2,"frozen_urls":["https://www.europarl.europa.eu/news/en/press-room/20261020IPR48312/"],"frozen_next":null}'::jsonb,'eu-parliament'),'snapshot ordinal cannot skip past end');
select ok(not has_function_privilege('anon','private.collector_cloud_frozen_cursor_valid(jsonb,text)','EXECUTE'),'snapshot validation grants no new public authority');
select * from finish();
rollback;
